#!/usr/bin/env python3
"""Run Agentic DocQA in a Google Colab GPU notebook, without Docker or GitHub keys.

1. In Colab choose Runtime > Change runtime type > a GPU (for example T4).
2. Upload this file using the notebook's Files sidebar.
3. Run:  %run /content/run_agentic_docqa_colab.py
4. Run:  docqa.upload()                      # choose PDF, MD or TXT files
5. Run:  docqa.ask("Summarize my document")

The original application runs on localhost; all interaction stays in the notebook.
The project source is embedded below so the private GitHub repo needs no credentials.
Setup mounts Google Drive and downloads Python packages, Ollama, and the models.
Source, model caches, documents, chats, account state and search-index backups are
saved under My Drive/Agentic DocQA. Allow the Drive mount prompt when Colab asks.
The live search database stays on local disk, with a Drive backup after each change.

Other commands:
    docqa.documents()                       # list indexed documents
    docqa.new_chat()                        # start another conversation
    docqa.save()                            # save a Drive checkpoint now
    docqa.upload("/content/example.pdf")    # upload a file already in Colab
    docqa.stop()                            # stop processes started by this file
    %run /content/run_agentic_docqa_colab.py --help
"""

